def lookup_rate(direction: str, service: str, zone: int, weight_kg: float, rate_type: str = "a26"):
    """
    Cari commercial rate UPS.
    """
    data_map = A26_RATES if rate_type.lower() == "a26" else B26_RATES
    table = data_map.get(direction, {}).get(service, {}).get(zone)
    
    if table is None:
        return None, None

    wt = weight_kg

    # Khusus envelope bisa ditangani di sini kalau service == 'envelope'
    if service == 'envelope':
        if 'env' in table:
            return table['env'], 'flat'
        elif 0.5 in table:
            return table[0.5], 'flat'
            
    # Flat mode: <=20kg
    if wt <= 20.0:
        rounded = round((wt * 2 + 0.999) // 1 / 2, 1)
        if rounded in table:
            return table[rounded], 'flat'
        
        # Fallback float
        float_keys = sorted(k for k in table if isinstance(k, float))
        for k in float_keys:
            if k >= wt - 0.001:
                return table[k], 'flat'

    # Per-kg mode: >20kg
    int_keys = sorted(k for k in table if isinstance(k, int) and k != 'min')
    for k in int_keys:
        if k == 300:
            if wt > 299:
                return table[k], 'perkg'
        else:
            if wt <= k:
                return table[k], 'perkg'

    return None, None
